#!/usr/bin/env bash
# Structure parity of Basalt vs vanilla worlds generated by the official server jar
# (tools/structure-world.sh, cached in vanilla/structures/, gitignored).
#
# usage: tools/structure-parity.sh [--quick] [--out DIR]
#   Sites: "<seed> <radius> <centre cx> <centre cz>". For each site it prints the per-structure-type
#   lines of `examples/structures compare` (STRUCT: starts vanilla/basalt/matched + jigsaw pieces
#   matched; BLOCKS: block-exact % inside the vanilla piece boxes of fully generated chunks, and the
#   same without structures) and one
#   `PARITY site=.. starts=<matched>/<vanilla> extra=<basalt-only> pieces=<m>/<n> blocks=<%> ok=0|1`.
#   Final line: `RESULT fuzz=structures cases=.. mismatches=.. new=.. errors=.. skipped=..`.
#   Thresholds: every vanilla start of a placed type found (types in KNOWN_TYPES may differ) and
#   jigsaw pieces 100 %, and block parity inside the piece boxes at least BLOCK_FLOOR per type (terrain
#   adaptation, 2026-11-24: villages / outposts 98.5, ancient cities 95, trial chambers 99, igloos and
#   swamp huts 97, desert pyramids 75 (98.4-99.9 unless vanilla sinks the box), jungle temples 85; a miss is
#   the mismatch class `blocks-<type>`). Known gaps: crates/check/known-divergences.txt lines `structures <type>`.
set -uo pipefail
cd "$(dirname "$0")/.."
OUT=target/check
QUICK=0
while [ $# -gt 0 ]; do
  case "$1" in
    --quick) QUICK=1; shift ;;
    --out) OUT=$2; shift 2 ;;
    *) break ;;
  esac
done
mkdir -p "$OUT"
# seed 12345: 64x64 chunks around the origin + one 16x16 site per village biome / outpost (found
# with /locate on vanilla); seeds 42 and 1: 64x64 around the origin; an igloo with a laboratory (12345) and
# a swamp hut (42), 4x4 chunks. Sites with a fifth field share one vanilla world with several small
# force-loaded squares (tools/structure-sites.sh SEED NAME R CX,CZ..., cached in
# vanilla/structures/<seed>_<name>): desert pyramids (incl. orientations 0/2 and one of the 3/9 boxes
# vanilla sinks 1-2 blocks) and jungle temples (incl. orientation 1).
TEMPLES_12345="-223,-312 -237,-312 -319,-303 -94,3 -105,12 -113,-20 -110,-55 -113,72 -146,66"
TEMPLES_42="-85,-109 197,149 -126,-232 -115,246 -140,-234 244,148 -84,181 9,-209 82,228"
TEMPLES_1="5,112 -150,19 -153,49"
SITES=("12345 32 0 0" "42 32 0 0" "1 32 0 0" "12345 8 10 55" "12345 8 -146 37" "12345 8 -66 -98" "12345 8 91 75" "12345 8 75 -23" "12345 8 17 -60" "12345 2 171 6" "42 2 144 -51"
  "12345 2 -223 -312 temples" "42 2 -115 246 temples" "42 2 -140 -234 temples" "42 2 -85 -109 temples"
  "12345 2 -110 -55 temples" "12345 2 -113 72 temples" "42 2 82 228 temples" "1 2 -150 19 temples")
[ $QUICK = 1 ] && SITES=("12345 8 10 55" "42 32 0 0")
KNOWN=${CHECK_KNOWN:-crates/check/known-divergences.txt}
cargo build --release -q -p basalt-worldgen --example structures 2>&1 | tail -5
T0=$(date +%s)
cases=0; bad=0; newbad=0; errors=0
for site in "${SITES[@]}"; do
  set -- $site
  seed=$1; R=$2; CX=$3; CZ=$4; multi=${5:-}
  dir=vanilla/structures/$seed
  [ "$CX" != 0 ] || [ "$CZ" != 0 ] && dir=vanilla/structures/${seed}_${CX}_${CZ}
  if [ -n "$multi" ]; then
    dir=vanilla/structures/${seed}_$multi
    eval "list=\$TEMPLES_$seed"
    gen=(tools/structure-sites.sh "$seed" "$multi" "$R" $list)
  else
    gen=(tools/structure-world.sh "$seed" "$R" "$CX" "$CZ")
  fi
  if ! "${gen[@]}" > "$OUT/structure-gen-$seed-$CX-$CZ.log" 2>&1; then
    echo "note: site $site: vanilla world generation failed"; errors=$((errors+1)); continue
  fi
  cases=$((cases+1))
  log=$OUT/structure-parity-$seed-$CX-$CZ.txt
  # Blocks are measured where Basalt places pieces (jigsaw + template structures).
  CENTER=$CX,$CZ BLOCK_TYPES=${BLOCK_TYPES:-village,pillager,trail,trial,ancient,shipwreck,ruined,ocean,igloo,swamp,desert,jungle} MAX_CHUNKS=${MAX_CHUNKS:-150} \
    ./target/release/examples/structures compare "$dir/world/dimensions/minecraft/overworld/region" "$R" "$seed" > "$log" 2>&1
  grep -E "^(STRUCT|BLOCKS)" "$log" | sed "s/^/  [$seed $CX,$CZ] /"
  verdict=$(python3 - "$log" "$KNOWN" <<'EOF'
import sys, re
log, known = sys.argv[1], sys.argv[2]
try:
    kn = {l.split()[1] for l in open(known) if l.startswith("structures ")}
except OSError:
    kn = set()
sv = sm = sx = pm = pn = 0
bad, new = [], []
for l in open(log):
    m = re.match(r"STRUCT (\S+)\s+vanilla=(\d+) basalt=(\d+) matched=(\d+) pieces=(\d+)/(\d+)", l)
    if not m: continue
    t, v, b, mt, a, n = m.group(1), *map(int, m.groups()[1:])
    sv += v; sm += mt; sx += b - mt
    jig = t.startswith(("village", "pillager", "trail", "trial", "ancient"))
    if jig: pm += a; pn += n
    ok = mt == v and b == mt and (not jig or a == n)
    if not ok:
        bad.append(t)
        if t not in kn: new.append(t)
FLOOR = {"village": 98.5, "pillager": 98.5, "ancient": 95.0, "trial": 99.0, "igloo": 97.0, "swamp": 97.0,
         "desert": 75.0, "jungle": 85.0}
for l in open(log):
    m = re.match(r"BLOCKS (\S+)\s+([\d.]+)% of (\d+)", l)
    if not m or int(m.group(3)) < 200: continue
    t, pct = m.group(1), float(m.group(2))
    fl = next((v for k, v in FLOOR.items() if t.startswith(k)), None)
    if fl is not None and pct < fl:
        c = "blocks-" + t
        bad.append(c)
        if c not in kn: new.append(c)
blocks = "n/a"
for l in open(log):
    m = re.search(r"blocks=([\d.]+)", l)
    if m: blocks = m.group(1)
print(("1" if not new else "0"), f"starts={sm}/{sv} extra={sx} pieces={pm}/{pn} blocks={blocks}", len(bad), len(new), ",".join(bad))
EOF
)
  set -- $verdict
  echo "PARITY site=$seed:$CX,$CZ,$R $2 $3 $4 $5 ok=$1${8:+ mismatch=$8}"
  bad=$((bad+$6)); newbad=$((newbad+$7))
done
echo "RESULT fuzz=structures cases=$cases mismatches=$bad new=$newbad info=0 errors=$errors skipped=0 secs=$(( $(date +%s) - T0 ))"
[ $newbad = 0 ] && [ $errors = 0 ]
